with base as (select id, email, country, signup_date, is_active, credit_limit, age, ceil(age) as age_whole from customers where age > 35), deduped as (select *, rank() over (partition by country order by credit_limit asc nulls last) as rank_in_group from base qualify rank_in_group = 1), kept as (select s.* from deduped s where not exists (select 1 from subscriptions c where c.customer_id = s.id and c.start_date <= s.signup_date)), eligible as (select s.* from kept s where not exists (select 1 from subscriptions x where x.customer_id = s.id and x.start_date >= s.signup_date)), filtered as (select *, substring(country, 1, 3) as country_prefix from eligible where signup_date >= to_date('2023-07-17')), not_flagged as (select s.* from filtered s where not exists (select 1 from accounts ch where ch.customer_id = s.id and ch.opened_date < s.signup_date)), stats as (select date_trunc('year', signup_date) as year_start, country, corr(credit_limit, age) as corr_credit_limit_age, round(sum(credit_limit) / nullif(count(case when country = 'UK' then 1 end), 0), 2) as credit_limit_per_uk, size(collect_set(country)) as num_countries from not_flagged group by date_trunc('year', signup_date), country) select year_start, country, credit_limit_per_uk, num_countries, case when country rlike '^(TH|DE)$' then 'EXTENDED' when country rlike '^(US|SG)$' then 'CORE' else 'OTHER_ZONE' end as country_zone from stats order by num_countries desc;
